(() => {
  const E=Engine, ix=E.indexCourse(typeof KOMOREBI_UNITS==='undefined'?[]:KOMOREBI_UNITS), KEY='komorebi-progress-v2';
  function track(event, props = {}) { try { window.PulseAnalytics?.track(event, props); } catch { /* optional */ } }
  const runProps = () => session ? {mode:session.mode,lesson_id:session.lessonId,unit_id:session.unitId,steps:session.steps.length,step_index:session.index} : {};
  const REPO='https://github.com/ionpetro/skepsis';
  const FAMILY = [
    {"id": "skepsis", "name": "Skepsis", "url": "https://tryskepsis.com", "repo": "https://github.com/ionpetro/skepsis", "en": "the Greek hiding in everyday English", "el": "οι ελληνικές ρίζες που κρύβονται στα αγγλικά"},
    {"id": "carpe", "name": "Carpe", "url": "https://carpe.tryskepsis.com", "repo": "https://github.com/ionpetro/carpe", "en": "Latin for Greece's national exams", "el": "Λατινικά για τις Πανελλαδικές"},
    {"id": "gnothi", "name": "Gnothi", "url": "https://gnothi.tryskepsis.com", "repo": "https://github.com/ionpetro/gnothi", "en": "Ancient Greek for Greece's national exams", "el": "Αρχαία Ελληνικά για τις Πανελλαδικές"},
    {"id": "objection", "name": "Objection", "url": "https://objection.tryskepsis.com", "repo": "https://github.com/ionpetro/objection", "en": "prep for the US bar exam", "el": "προετοιμασία για τις εξετάσεις δικηγόρων των ΗΠΑ"},
    {"id": "agora", "name": "Agora", "url": "https://agora.tryskepsis.com", "repo": "https://github.com/ionpetro/agora", "en": "sales and negotiation, with ethics", "el": "πωλήσεις και διαπραγμάτευση, με ηθική"},
    {"id": "oikos", "name": "Oikos", "url": "https://oikos.tryskepsis.com", "repo": "https://github.com/ionpetro/oikos", "en": "economics and incentives", "el": "οικονομικά και κίνητρα"},
    {"id": "guanxi", "name": "Guanxi", "url": "https://guanxi.tryskepsis.com", "repo": "https://github.com/ionpetro/guanxi", "en": "Mandarin and local culture", "el": "Μανδαρινικά και τοπική κουλτούρα"},
    {"id": "everyday-ethics", "name": "Everyday Ethics", "url": "https://ethics.tryskepsis.com", "repo": "https://github.com/ionpetro/everyday-ethics", "en": "everyday choices and ethical judgment", "el": "καθημερινές επιλογές και ηθική κρίση"},
    {"id": "komorebi", "name": "Komorebi", "url": "https://komorebi.tryskepsis.com", "repo": "https://github.com/ionpetro/komorebi", "en": "Japanese through everyday life", "el": "Ιαπωνικά μέσα από την καθημερινή ζωή"},
  ];
  const root=document.getElementById('app');
  let storageOK=true,state;
  try{state=E.repairState(JSON.parse(localStorage.getItem(KEY)||'null'));}catch{state=E.freshState();storageOK=false;}
  if(!state.onboarded&&(state.xp>0||state.answered>0||Object.keys(state.done||{}).length||Object.keys(state.sittings||{}).length||Object.keys(state.items||{}).length)){state.onboarded=true;}
  let view='home',selectedUnit=null,kanaScript='hiragana',kanaRow='vowels',session=null,feedback=null,timerId=null,tiles=[],match={left:null,right:null,done:[]},sort={},retry=[],notice='',voices=[];
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const attr=esc;
  const today=()=>E.dayKey();
  function save(){state.updatedAt=Date.now();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}}
  function availableVoices(){if(!('speechSynthesis' in window))return[];return speechSynthesis.getVoices().filter(v=>/^ja(?:[-_]|$)/i.test(v.lang));}
  function updateVoices(){const nextVoices=availableVoices();if(nextVoices.map(v=>v.voiceURI).join('|')===voices.map(v=>v.voiceURI).join('|'))return;const pending=[...document.querySelectorAll('input[id],select[id]')].filter(el=>el.type!=='file'&&el.id!=='setting-voice').map(el=>({id:el.id,value:el.value,checked:el.checked}));voices=nextVoices;if(state.voice&&!voices.some(v=>v.voiceURI===state.voice)){state.voice='';save();}render();for(const previous of pending){const el=document.getElementById(previous.id);if(el){el.value=previous.value;if(el.type==='checkbox')el.checked=previous.checked;if(el.id==='word-search')el.dispatchEvent(new Event('input',{bubbles:true}));}}}
  if('speechSynthesis' in window){speechSynthesis.addEventListener?.('voiceschanged',updateVoices);setTimeout(updateVoices,400);setTimeout(updateVoices,1600);}
  function selectedVoice(){return voices.find(v=>v.voiceURI===state.voice)||voices[0]||null;}
  function speak(ja,slow=false){const v=selectedVoice();if(!v){notice='No Japanese voice is available on this device. Read the phrase aloud using the reading guide.';if(view!=='session')render();return false;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(ja);u.lang='ja-JP';u.voice=v;u.rate=slow?0.68:0.9;u.onerror=e=>{if(e.error==='interrupted'||e.error==='canceled')return;voices=[];notice='Japanese audio could not play. You can continue with ungraded read-and-say practice.';render();};speechSynthesis.speak(u);return true;}

  function audioButton(ja,label='Hear it'){return `<button class="btn ghost small" type="button" data-act="speak" data-text="${attr(ja)}" ${voices.length?'':'disabled title="No Japanese voice available; see Settings"'} aria-label="${attr(label)}"><span>${esc(label)}</span></button>`;}
  const I = {
    star: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="m12 2.5 2.8 6.3 6.7.6-5.1 4.5 1.5 6.7L12 17.1l-5.9 3.5 1.5-6.7L2.5 9.4l6.7-.6z"/></svg>',
    github: '<svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59.4.07.55-.17.55-.38v-1.33c-2.23.48-2.7-1.07-2.7-1.07-.36-.92-.89-1.17-.89-1.17-.73-.5.06-.49.06-.49.8.06 1.23.83 1.23.83.72 1.22 1.87.87 2.33.66.07-.52.28-.87.5-1.07-1.78-.2-3.65-.89-3.65-3.95 0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82a7.6 7.6 0 0 1 4 0c1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 3.95.29.25.54.73.54 1.48v2.2c0 .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8z"/></svg>',
    flame: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2c1 3.5-1.6 5.3-2.9 7.3C7.6 11.5 7 13 7 14.6 7 18.1 9.3 21 12 21s5-2.6 5-6.2c0-2.1-.9-3.7-2-5 .1 1.6-.5 2.8-1.6 3.3.5-3.6-.6-7.6-1.4-11.1z"/></svg>',
    coin: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9.5" fill="currentColor"/><text x="12" y="16.5" text-anchor="middle" font-family="Georgia,serif" font-size="12" font-weight="700" fill="var(--surface)">ὀ</text></svg>',
    truce: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 3c-2 2-4 2.5-7 2.5V12c0 4.5 3 7.5 7 9 4-1.5 7-4.5 7-9V5.5C16 5.5 14 5 12 3z"/><path d="M9 12.5c1.5-1 4.5-1 6 0M9 9.5c1.5 1 4.5 1 6 0"/></svg>',
    road: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 21 9 3h6l4 18"/><path d="M12 6v2M12 11v2.5M12 16.5V19"/></svg>',
    scroll: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 4h11a2 2 0 0 1 2 2v1h-4M7 4a2 2 0 0 0-2 2v12a2 2 0 0 1-2 2h11a2 2 0 0 0 2-2V6a2 2 0 0 0-2-2M8.5 9h5M8.5 13h5"/></svg>',
    column: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M4 4h16M5 7h14M8 7v11M12 7v11M16 7v11M4 20h16M6 18h12"/></svg>',
    redo: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 11a8 8 0 1 0-2.3 5.7M20 4v7h-7"/></svg>',
    runner: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="15" cy="4.5" r="2"/><path d="M13 9l-4 1-2 4M13 9l2.5 3.5-1 5.5M13 9l5 2 2 3M9.5 13.5 7 20"/></svg>',
    cal: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M3 10h18M8 3v4M16 3v4"/></svg>',
    paper: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M6 3h9l4 4v14H6z"/><path d="M15 3v4h4M9 12h6M9 16h6"/></svg>',
    cards: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linejoin="round" aria-hidden="true"><rect x="4" y="6" width="12" height="15" rx="2"/><path d="M8 3h11a1 1 0 0 1 1 1v13"/></svg>',
    x: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18"/></svg>',
    check: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg>',
    olive: '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 3c-1 2-1 4 0 6 1-2 1-4 0-6zm-5 3c0 2 1 4 3 5-0-2-1-4-3-5zm10 0c-2 1-3 3-3 5 2-1 3-3 3-5zM5 11c1 2 3 3 5 3-1-2-3-3-5-3zm14 0c-2 0-4 1-5 3 2 0 4-1 5-3zM6 16c2 1 4 1 6 0-2-1-4-1-6 0zm12 0c-2-1-4-1-6 0 2 1 4 1 6 0z"/></svg>',
  };
  function wreath(letter) {
    return `<svg viewBox="0 0 48 48" aria-hidden="true"><g fill="var(--olive)">${[...Array(6)].map((_, i) => {
      const a = (200 + i * 26) * Math.PI / 180, b = (-20 - i * 26) * Math.PI / 180;
      const p = (t) => [24 + 19 * Math.cos(t), 26 + 19 * Math.sin(t)];
      const [x1, y1] = p(a), [x2, y2] = p(b);
      return `<ellipse cx="${x1.toFixed(1)}" cy="${y1.toFixed(1)}" rx="3" ry="6" transform="rotate(${(a * 180 / Math.PI + 90).toFixed(0)} ${x1.toFixed(1)} ${y1.toFixed(1)})"/><ellipse cx="${x2.toFixed(1)}" cy="${y2.toFixed(1)}" rx="3" ry="6" transform="rotate(${(b * 180 / Math.PI + 90).toFixed(0)} ${x2.toFixed(1)} ${y2.toFixed(1)})"/>`;
    }).join("")}</g><text x="24" y="31" text-anchor="middle" font-family="GFS Didot, Noto Serif, Georgia, serif" font-weight="700" font-size="19" fill="var(--ink)">${esc(letter)}</text></svg>`;
  }

  function mascot(mood='happy'){
    const happy=mood==='cheer', sleepy=mood==='sleepy';
    return `<svg class="mascot" viewBox="0 0 130 130" role="img" aria-label="Komo the fox, your course companion"><ellipse cx="65" cy="121" rx="44" ry="5" fill="var(--line)"/><path d="M84 87q47-8 30 24-15 17-40-6" fill="#d98042"/><path d="M109 94q17 7 4 19l-13-10" fill="#fff5dc"/><ellipse cx="65" cy="93" rx="29" ry="30" fill="#d98042"/><ellipse cx="65" cy="98" rx="19" ry="23" fill="#fff5dc"/><path d="M27 55 22 10 53 32M103 55l5-45-31 22" fill="#d98042" stroke="#a44e29" stroke-width="3" stroke-linejoin="round"/><path d="m29 22 5 24 13-10M101 22l-5 24-13-10" fill="#f7c1a5"/><path d="M25 51q40-43 80 0l-9 31q-31 27-62 0z" fill="#e9964f"/><path d="M26 57q22-1 39 21 17-22 39-21l-8 25q-31 27-62 0z" fill="#fff5dc"/>${sleepy?'<path d="m42 56 10 2m26 0 10-2" stroke="#352e39" stroke-width="4"/>':'<ellipse cx="47" cy="56" rx="4.5" ry="6" fill="#352e39"/><ellipse cx="83" cy="56" rx="4.5" ry="6" fill="#352e39"/><circle cx="48" cy="54" r="1.5" fill="white"/><circle cx="84" cy="54" r="1.5" fill="white"/>'}<path d="m59 76 6 6 6-6z" fill="#352e39"/><path d="M65 82q-7 9-13 1m13-1q7 9 13 1" stroke="#352e39" stroke-width="2" fill="none"/><path d="M40 100q25 10 50 0" stroke="var(--brand)" stroke-width="9"/><path d="m80 102 8 14 8-13" fill="var(--brand)"/><path d="M43 118h14m16 0h14" stroke="#a44e29" stroke-width="6" stroke-linecap="round"/>${happy?'<path d="m12 60 4-8 4 8 8 4-8 4-4 8-4-8-8-4z" fill="var(--gold)"/>':''}</svg>`;
  }

  function header(){const st=E.liveStreak(state,today()),active=state.lastDay===today();return `<header class="topbar"><div class="topbar-main"><div class="wordmark">Komorebi<small>日本語</small></div><div class="stats"><span class="stat flame ${active?'':'cold'}" title="Learning streak">${I.flame}<span>${st}</span></span><span class="stat" title="Streak freezes" style="color:var(--brand)">${I.truce}<span>${state.freezes}</span></span><span class="stat xp" title="Experience points">${I.olive}<span>${state.xp}</span></span></div></div><a class="gh" href="${REPO}" target="_blank" rel="noopener" aria-label="Explore the Skepsis learning family" title="Explore the Skepsis learning family">${I.github}<span class="gh-label">${I.star}<span class="gh-text">Family</span></span></a></header>`;}
  function tabbar(){const current=view==='glossary'||view==='kana'?'words':view==='settings'?'me':'learn';return `<nav class="tabbar" aria-label="Main navigation"><div class="tabbar-inner"><button class="tab" data-act="home" ${current==='learn'?'aria-current="page"':''}>${I.road}<span>Learn</span></button><button class="tab" data-act="glossary" ${current==='words'?'aria-current="page"':''}>${I.scroll}<span>Words</span></button><button class="tab" data-act="settings" ${current==='me'?'aria-current="page"':''}>${I.column}<span>Me</span></button></div></nav>`;}
  function japanese(it){return `<ruby lang="ja">${esc(it.ja)}${it.kana&&it.kana!==it.ja?`<rt>${esc(it.kana)}</rt>`:''}</ruby>`;}
  function sectionTitle(kicker,title,sub=''){return `<section class="col" style="gap:6px"><div class="eyebrow">${esc(kicker)}</div><h1>${esc(title)}</h1>${sub?`<p class="muted" style="font-weight:700">${esc(sub)}</p>`:''}</section>`;}
  function onboarding(){return `<div class="onboard">${mascot('cheer')}<h1>Komorebi</h1><p class="tag-line">A little Japanese. A little closer.</p><p class="lede">Meet the language through everyday life. Short lessons, real conversations, and the culture between the words.</p><div class="card col"><label for="ob-name" style="font-weight:900">What should we call you?</label><input type="text" id="ob-name" placeholder="Your name (optional)" value="${attr(state.name)}" autocomplete="given-name" maxlength="30"><h3>How much each day?</h3><div class="goalopts">${E.GOALS.map(g=>`<button class="goalopt" data-act="onboard-goal" data-value="${g}" aria-pressed="${state.goal===g}"><b>${g} XP</b><small>${g===10?'A short sitting':g===20?'A steady routine':'A longer practice'}</small></button>`).join('')}</div></div><button class="btn block gold" data-act="start-course">Start learning</button><p class="muted" style="text-align:center;font-size:13px;font-weight:700">Weekends do not break your streak. Progress stays in this browser.</p><footer class="sitenote"><a href="/about/">About</a> · <a href="/glossary/">Glossary</a></footer></div>`;}
  function via(){const next=E.recommended(ix,state);return `<section class="via"><h2>Course path</h2>${ix.units.map((u,i)=>{const done=u.lessons.filter(l=>state.done[l.id]).length,started=done>0||u.lessons.some(l=>state.sittings[l.id]),complete=done===u.lessons.length;return `<div class="milestone"><div class="mile ${complete?'done':started?'open':''}">${i+1}</div><div class="ucard"><div class="row" style="justify-content:space-between;align-items:flex-start"><h2>${esc(u.title)}</h2><div class="exam-tags"><span class="tag">${esc(u.place||'Tokyo')}</span></div></div><p>${esc(u.blurb||u.focus)}</p><div class="ubar"><i style="width:${Math.round(done/u.lessons.length*100)}%"></i></div><div class="stones">${u.lessons.map((l,j)=>{const isdone=!!state.done[l.id],current=next?.id===l.id,count=E.lessonSittings(ix,l.id).length,sits=state.sittings[l.id]||0;return `<button class="stone ${isdone?'done':''} ${current?'current':''}" data-act="start-lesson" data-id="${attr(l.id)}" title="${attr(l.title)}" aria-label="${attr(l.title)}${isdone?' (completed)':''}">${isdone?I.check:j+1}${count>1&&!isdone?`<span class="sit">${sits}/${count}</span>`:''}</button>`}).join('')}<button class="stone boss" data-act="start-assessment" data-id="${attr(u.id)}" title="Scenario assessment" aria-label="${attr(u.title)} scenario assessment">${I.paper}</button></div><button class="linkbtn" data-act="open-unit" data-id="${attr(u.id)}">See chapter and scenes →</button></div></div>`}).join('')}</section>`;}
  function home(){const p=E.progress(ix,state),next=E.recommended(ix,state),due=E.dueItems(state,today()).filter(id=>ix.items.has(id)&&!ix.assessmentItems.has(id)).length,daily=state.days[today()]||0,pct=Math.min(1,daily/state.goal),C=2*Math.PI*24,misses=Object.keys(state.mistakes).filter(id=>ix.items.has(id)&&!ix.assessmentItems.has(id)&&state.mistakes[id]>0).length,dayWords=[...ix.items.values()].filter(it=>it.kind==='word'),word=dayWords[Math.abs(Number(today().replace(/-/g,'')))%dayWords.length];return `<section class="hero">${mascot(daily>=state.goal?'cheer':'happy')}<div class="bubble">${state.name?esc(state.name)+', ':''}${daily>=state.goal?'you reached today’s goal. Well done.':'ready for a few minutes of Japanese?'}</div></section><section class="countdown"><div class="n tnum">${p.done}<small>LESSONS</small></div><div><div class="ph">Your course progress<b>${p.done} of ${p.total} lessons complete</b></div><div class="road">${[1,2,3].map(k=>`<i class="${p.percent>=(k-1)*33+1?'on':''}"></i>`).join('')}</div><div class="pace">Twelve open chapters. Follow the suggested route or explore any lesson.</div></div></section><section class="card goalring"><svg viewBox="0 0 58 58" aria-hidden="true"><circle class="track" cx="29" cy="29" r="24" fill="none" stroke-width="8"/><circle class="fill" cx="29" cy="29" r="24" fill="none" stroke-width="8" stroke-linecap="round" stroke-dasharray="${C.toFixed(1)}" stroke-dashoffset="${(C*(1-pct)).toFixed(1)}"/></svg><div style="flex:1;min-width:0"><div class="eyebrow">Daily goal</div><h3 class="tnum">${daily} / ${state.goal} XP</h3><p class="muted" style="font-weight:700;font-size:14px">Weekends do not break your streak.</p></div>${next?`<button class="btn" data-act="start-lesson" data-id="${attr(next.id)}">${state.sittings[next.id]?'Continue':'Start'}</button>`:''}</section><section class="quick"><button class="tile" data-act="kana"><span style="color:var(--brand);font-size:26px;font-weight:900" lang="ja">あ</span><b>Kana garden</b><span>Hiragana · katakana · sound length</span></button><button class="tile" data-act="culture"><span style="color:var(--clay)">${I.olive}</span><b>Culture journal</b><span>Everyday context & chapter stamps</span></button><button class="tile ${state.daily[today()]?'done':''}" data-act="start-daily"><span style="color:var(--brand)">${I.cal}</span><b>Daily drill</b><span>${state.daily[today()]?`Today: ${state.daily[today()].score}/${state.daily[today()].total}`:'Five small questions'}</span></button><button class="tile" data-act="start-review" ${due?'':'disabled'}><span style="color:var(--olive)">${I.redo}</span><b>Spaced review</b><span>${due?`${due} cards due today`:'No cards due today'}</span></button><button class="tile" data-act="start-speed"><span style="color:var(--flame)">${I.runner}</span><b>Lantern sprint</b><span>15 seconds each · best ${state.speedBest}/10</span></button><button class="tile" data-act="review"><span style="color:var(--gold-deep)">${I.paper}</span><b>Practice desk</b><span>Listening, matching, sorting and more</span></button><button class="tile" data-act="glossary"><span style="color:var(--brand)">${I.cards}</span><b>Words</b><span>${[...ix.items.values()].filter(it=>['word','character'].includes(it.kind)).length} course cards</span></button><button class="tile" data-act="start-mistakes" ${misses?'':'disabled'}><span style="color:var(--clay)">${I.scroll}</span><b>Mistakes notebook</b><span>${misses?`${misses} cards to revisit`:'Opens after a missed card'}</span></button></section>${word?`<section class="card wotd col" style="gap:6px"><div class="eyebrow">Word of the day</div><div class="row" style="flex-wrap:wrap;align-items:baseline;gap:4px 12px"><span class="big grc" lang="ja">${japanese(word)}</span><span class="sub romaji">${esc(word.romaji)}</span></div><p style="font-weight:800">${esc(word.meaning)}</p></section>`:''}${notice?`<p class="card" role="status">${esc(notice)}</p>`:''}${via()}`;}
  function map(){return via();}
  function unitPage(){const u=ix.unitById.get(selectedUnit);if(!u)return via();return `<button class="linkbtn" data-act="home">← Course path</button>${sectionTitle(u.place||'Tokyo',u.title,u.blurb)}<section class="col">${u.lessons.map((l,i)=>`<article class="card col"><div class="eyebrow">${state.done[l.id]?'Complete':state.sittings[l.id]?'In progress':`Lesson ${i+1}`}</div><h2>${esc(l.title)}</h2><p class="muted">${esc(l.scene)}</p><button class="btn small" data-act="start-lesson" data-id="${attr(l.id)}">${state.done[l.id]?'Revisit':state.sittings[l.id]?'Continue':'Begin'}</button></article>`).join('')}<article class="card col"><div class="eyebrow">Scenario assessment</div><h2>Try the situation</h2><p class="muted">Use what you have learned to make a choice in a new scene.</p><button class="btn" data-act="start-assessment" data-id="${attr(u.id)}">Start assessment</button></article></section>`;}
  function reviewPage(){const due=E.dueItems(state,today()).filter(id=>ix.items.has(id)&&!ix.assessmentItems.has(id)),misses=Object.entries(state.mistakes).filter(([id,n])=>ix.items.has(id)&&!ix.assessmentItems.has(id)&&n>0).sort((a,b)=>b[1]-a[1]),canSort=!!E.buildSort(ix,state,1),canListen=E.learned(ix,state).some(id=>['word','character'].includes(ix.items.get(id)?.kind));return `<button class="linkbtn" data-act="home">← Learn</button>${sectionTitle('Practice desk','Recall and repair','Review cards return after 1, 3, 7, 14, 30 and 60 days.')}<section class="quick"><button class="tile" data-act="start-review" ${due.length?'':'disabled'}><span style="color:var(--olive)">${I.redo}</span><b>Due cards</b><span>${due.length} ready today</span></button><button class="tile" data-act="start-daily"><span style="color:var(--brand)">${I.cal}</span><b>Daily drill</b><span>Five short questions</span></button><button class="tile" data-act="start-speed"><span style="color:var(--flame)">${I.runner}</span><b>Lantern sprint</b><span>One miss ends the round</span></button><button class="tile" data-act="start-listening" ${canListen?'':'disabled'}><span style="color:var(--brand)">${I.cards}</span><b>Listening</b><span>${canListen?'Learned words only':'Learn a word to unlock'}</span></button><button class="tile" data-act="start-match"><span style="color:var(--gold-deep)">${I.paper}</span><b>Matching</b><span>Match learned expressions</span></button><button class="tile" data-act="start-sort" ${canSort?'':'disabled'}><span style="color:var(--olive)">${I.column}</span><b>Sorting</b><span>${canSort?'Sort learned words':'Learn four words from a themed pair to unlock'}</span></button><button class="tile" data-act="start-mistakes" ${misses.length?'':'disabled'}><span style="color:var(--clay)">${I.scroll}</span><b>Mistakes</b><span>${misses.length} cards to revisit</span></button></section>${misses.length?`<section class="card col"><h2>Mistakes notebook</h2>${misses.slice(0,12).map(([id,n])=>{const it=ix.items.get(id);return `<p><b>${esc(it.ja||it.title||it.scene||it.q)}</b> · ${n} misses</p>`}).join('')}</section>`:''}`;}
  const STAMPS=['会','食','道','店','日','家','友','学','季','旅','助','縁'];
  function stampBook(){return `<section class="card col"><div class="eyebrow">Your travel journal</div><h2>Small steps. Lasting memories.</h2><p class="muted">Earn a chapter stamp by completing its five lessons. These are course keepsakes, inspired by travel stamp collecting.</p><div class="stampbook">${ix.units.map((u,i)=>{const count=u.lessons.filter(l=>state.done[l.id]).length;return `<div class="stamp-entry"><span class="stamp ${count===u.lessons.length?'':'off'}" lang="ja">${STAMPS[i]}</span><span>${esc(u.title)}<br>${count}/${u.lessons.length}</span></div>`}).join('')}</div></section>`;}
  function culturePage(){return `<button class="linkbtn" data-act="home">← Learn</button>${sectionTitle('Culture journal','Learn the context, too.','Language belongs to people and places. Notice the situation, ask when unsure, and leave room for individual preferences.')}${stampBook()}${ix.units.map(u=>`<section class="col"><h2>${esc(u.title)}</h2>${u.lessons.flatMap(l=>l.items.filter(it=>it.kind==='culture')).map(it=>`<details class="card culture-card"><summary>${esc(it.title)}</summary><p style="margin-top:12px">${esc(it.body)}</p>${it.phrase?`<p>${japanese(it.phrase)} <span class="romaji">${esc(it.phrase.romaji)}</span> · ${esc(it.phrase.meaning)}</p>`:''}${sourceLink(it)}</details>`).join('')}</section>`).join('')}`;}
  function kanaPage(){const cards=Kana.select(kanaScript,kanaRow),known=Kana.cards.filter(c=>state.kanaProgress[c.id]?.right>0).length;return `<button class="linkbtn" data-act="home">← Learn</button>${sectionTitle('Kana garden','Read a little more each day.','Hiragana and katakana, alongside your everyday Japanese. Start with a row; come back when the symbols are due.')}<section class="card col"><b>${known} / ${Kana.cards.length} symbols and combinations practiced</b><div class="kana-controls">${['hiragana','katakana'].map(t=>`<button class="goalopt" data-act="kana-script" data-value="${t}" aria-pressed="${kanaScript===t}">${t==='hiragana'?'あ Hiragana':'ア Katakana'}</button>`).join('')}</div><div class="kana-controls"><label for="kana-row">Practice set</label><select id="kana-row"><option value="basic" ${kanaRow==='basic'?'selected':''}>All 46 basic kana</option>${Kana.rows.map(([id,title])=>`<option value="${id}" ${kanaRow===id?'selected':''}>${title}</option>`).join('')}<option value="all" ${kanaRow==='all'?'selected':''}>All symbols + combinations</option></select></div><button class="btn block" data-act="start-kana">Practice this set</button><p class="muted">New symbols are introduced before recall. A miss returns tomorrow. Tap any tile to hear it when a Japanese voice is available.</p></section>${notice?`<p class="card" role="status">${esc(notice)}</p>`:''}<section class="kana-grid">${cards.map(c=>`<button class="kana-cell ${state.kanaProgress[c.id]?.right?'known':''}" data-act="speak" data-text="${attr(c.ja)}" aria-label="${attr(c.ja+' — '+c.romaji)}"><b lang="ja">${esc(c.ja)}</b><small>${esc(c.romaji)}</small></button>`).join('')}</section><section class="card col"><h2>Hear the difference</h2><p>Japanese timing matters. Long vowels, small っ, and ん take time. Roman letters are a reading aid, not a pronunciation grade.</p>${[['おばさん','obasan','aunt'],['おばあさん','obāsan','grandmother / elderly woman'],['きて','kite','come (request form)'],['きって','kitte','postage stamp'],['コーヒー','kōhī','coffee']].map(([ja,r,m])=>`<div class="row" style="flex-wrap:wrap"><b lang="ja">${ja}</b><span>${r} · ${m}</span>${audioButton(ja,'Listen')}</div>`).join('')}<p class="hint">Small っ marks a held consonant; small ゃゅょ combine with the preceding kana. Katakana ー extends the preceding vowel. The particles は, へ, を are pronounced wa, e, o. ぢ/じ and づ/ず share readings in standard Japanese; spelling depends on the word.</p><a class="source" href="https://www.irodori.jpf.go.jp/assets/data/starter/pdf/X_L02.pdf" target="_blank" rel="noopener">Japan Foundation: sounds and communication ↗</a></section>`;}
  function glossary(){const words=[...ix.items.values()].filter(it=>['word','character'].includes(it.kind));return `${sectionTitle('Lexicon',`${words.length} words and phrases`,'Browse course vocabulary. Audio uses a Japanese voice in your browser when available.')}<button class="btn ghost small" data-act="kana">Open kana garden →</button><input class="search" id="word-search" type="search" placeholder="Search Japanese, reading or meaning…" autocomplete="off" aria-label="Search words"><section id="word-list" class="lex">${wordRows(words)}</section>`;}
  function wordRows(words){return words.map(it=>`<article class="card lexcard"><div class="lexhead"><b lang="ja">${japanese(it)}</b><span class="sub romaji">${esc(it.romaji)}</span><span class="m">${esc(it.meaning)}</span></div><p class="say">${esc(it.say||'')}</p>${audioButton(it.ja,'Hear '+it.ja)}</article>`).join('');}
  function settings(){const p=E.progress(ix,state),acc=state.answered?Math.round(state.correct/state.answered*100):0,rank=E.rankOf(state).rank;return `<section class="hero">${mascot()}<div class="bubble">${p.learned?`You have learned ${p.learned} cards. Your rank is ${esc(rank.name)}.`:'Complete a lesson to start your collection.'}</div></section><section class="grid2">${[['Lessons',`${p.done}/${p.total}`],['XP',state.xp],['Best streak',`${state.bestStreak} days`],['Accuracy',`${acc}%`],['Speed best',state.speedBest],['Rank',esc(rank.name)]].map(([h,v])=>`<div class="card"><div class="eyebrow">${h}</div><h2 class="tnum">${v}</h2></div>`).join('')}</section>${stampBook()}<section class="col"><h2>Milestones</h2><div class="badges">${E.BADGES.map(b=>`<div class="badge ${state.badges[b.id]?'':'off'}">${wreath(b.name.charAt(0))}<b>${esc(b.name)}</b><span>${state.badges[b.id]?'Earned '+esc(state.badges[b.id]):esc(b.hint)}</span></div>`).join('')}</div></section><section class="card"><div class="setting"><div><label for="setting-name">Name</label><small>How the course greets you</small></div><input type="text" id="setting-name" value="${attr(state.name)}" maxlength="40"></div><div class="setting" style="flex-direction:column;align-items:stretch"><label>Daily goal</label><div class="goalopts">${E.GOALS.map(g=>`<button class="goalopt" data-act="set-goal" data-value="${g}" aria-pressed="${state.goal===g}"><b>${g} XP</b><small>${g===10?'A short sitting':g===20?'A steady routine':'A longer practice'}</small></button>`).join('')}</div></div><div class="setting"><div><label for="setting-theme">Appearance</label></div><select id="setting-theme"><option value="auto" ${state.theme==='auto'?'selected':''}>Follow device</option><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select></div><div class="setting"><div><label for="setting-voice">Japanese voice</label><small>${voices.length?'Browser speech, not a pronunciation grade':'No Japanese voice detected'}</small></div><select id="setting-voice"><option value="">${voices.length?'Automatic Japanese voice':'No Japanese voice detected'}</option>${voices.map(v=>`<option value="${attr(v.voiceURI)}" ${state.voice===v.voiceURI?'selected':''}>${esc(v.name)} (${esc(v.lang)})</option>`).join('')}</select></div><div class="setting"><div><label for="setting-romaji">Romaji support</label><small>Hide as you become comfortable with kana</small></div><input id="setting-romaji" type="checkbox" ${state.showRomaji!==false?'checked':''}></div><div class="setting"><div><label for="setting-kana">Kana readings</label><small>Show readings above Japanese text</small></div><input id="setting-kana" type="checkbox" ${state.showKana!==false?'checked':''}></div><div class="setting"><div><label>Streak freezes: ${state.freezes}</label><small>Weekends do not break your streak. A missed weekday uses one freeze. At least one refills each Monday, up to two.</small></div></div><div class="setting"><div><label>Local progress</label><small>${storageOK?'Saved on this device':'Storage unavailable; export before closing'}</small></div><div class="row"><button class="btn ghost small" data-act="export">Export</button><label class="btn ghost small">Import<input id="import-file" type="file" accept="application/json,.json" hidden></label></div></div><div class="setting"><button class="btn block" data-act="save-settings">Save settings</button></div></section><button class="linkbtn" data-act="review">Open practice desk →</button>${notice?`<p class="card" role="status">${esc(notice)}</p>`:''}`;}
  function teachCard(it){let body='';if(['word','character','sentence'].includes(it.kind))body=`<div class="bigword">${japanese(it)}</div><div class="sub romaji">${esc(it.romaji)}</div><div class="meaning">${esc(it.meaning)}</div>${audioButton(it.ja)}${voices.length?`<button class="btn ghost small" data-act="slow" data-text="${attr(it.ja)}">Slow replay</button>`:''}`;if(it.kind==='grammar')body=`<h2>${esc(it.title)}</h2><p>${esc(it.explanation)}</p><div class="exlist">${(it.examples||[]).map(ex=>`<div class="ex"><b>${japanese(ex)}</b><span class="romaji">${esc(ex.romaji)}</span><small>${esc(ex.meaning)}${ex.spokenRomaji?` · Spoken: ${esc(ex.spokenRomaji)}`:''}</small>${audioButton(ex.ja)}</div>`).join('')}</div>`;if(it.kind==='culture')body=`<h2>${esc(it.title)}</h2><p>${esc(it.body)}</p>${it.phrase?`<div class="card col"><b>${esc(it.phrase.ja)}</b><span>${esc(it.phrase.romaji)}</span><small>${esc(it.phrase.meaning)}</small>${audioButton(it.phrase.ja)}</div>`:''}`;if(it.kind==='pairs'||it.kind==='sort')body=`<h2>${esc(it.title)}</h2><p>${esc(it.say)}</p>`;return `<div class="intro">${body}${it.spokenRomaji?`<p class="hint"><b>In connected speech:</b> ${esc(it.spokenRomaji)}</p>`:''}${it.note?`<p class="hint"><b>Notice:</b> ${esc(it.note)}</p>`:''}${it.hook?`<p class="hint">${esc(it.hook)}</p>`:''}<p class="story">${esc(it.say)}</p>${sourceLink(it)}</div>`;}
  function sourceLink(it){
    const src=it?.src;if(!src)return'';
    const bank=typeof KOMOREBI_SOURCES==='object'?KOMOREBI_SOURCES:{};
    const match=Object.keys(bank).find(id=>src===id||src.endsWith(' '+id)||src.endsWith(': '+id));
    if(match){const data=bank[match];return `<a class="source" href="${attr(data.url)}" target="_blank" rel="noopener noreferrer">${src===match?'Source':'Context'}: ${esc(data.title)} · ${esc(data.publisher)} ↗</a>`;}
    if(/^https?:\/\//.test(src))return `<a class="source" href="${attr(src)}" target="_blank" rel="noopener noreferrer">Source and further reading ↗</a>`;
    return src.startsWith('Original')?'<span class="source">Original teaching example</span>':`<span class="source">${esc(src)}</span>`;
  }
  function questionCard(q){const fb=feedback, it=ix.items.get(q.itemId);let body='';
    if(q.type==='choice'||q.type==='kana-choice')body=`${q.ja?`<div class="bigword">${japanese(q)}</div>${q.romaji?`<div class="sub romaji">${esc(q.romaji)}</div>`:''}${q.type==='kana-choice'?'':audioButton(q.ja)}`:''}<h2>${esc(q.prompt)}</h2><div class="options">${q.options.map((o,i)=>`<button data-act="answer" data-value="${attr(o)}" ${fb?'disabled':''} class="opt ${fb&&E.norm(o)===E.norm(q.answer)?'right':''}"><span class="k">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>`;
    if(q.type==='listen')body=voices.length?`<h2>Listen and choose the meaning</h2><p>Play the Japanese phrase, then choose what it means. You can hear it again slowly.</p>${audioButton(q.ja,'Play phrase')}<button class="btn ghost small" data-act="slow" data-text="${attr(q.ja)}">Slow replay</button><div class="options">${q.options.map((o,i)=>`<button data-act="answer" data-value="${attr(o)}" ${fb?'disabled':''} class="opt ${fb&&E.norm(o)===E.norm(q.answer)?'right':''}"><span class="k">${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>`:`<h2>Read and say it aloud</h2><p>No Japanese voice is available. This is visual practice, without a listening score.</p><div class="bigword">${japanese(q)}</div><div class="sub romaji">${esc(q.romaji)}</div>${fb?'':`<button class="btn" data-act="listen-reveal">Reveal meaning →</button>`}`;
    if(q.type==='scenario')body=`<span class="eyebrow">${esc(q.title)}</span><p class="pass">${esc(q.scene)}</p><h2>${esc(q.prompt)}</h2><div class="options">${q.options.map((o,i)=>`<button data-act="answer" data-value="${i}" ${fb?'disabled':''} class="opt ${fb&&i===q.answer?'right':''}"><span class="k">${String.fromCharCode(65+i)}</span>${esc(o.text)}</button>`).join('')}</div>`;
    if(q.type==='tiles'){const used=new Set(tiles),selected=tiles.map(k=>q.tiles.find(t=>t.key===k)).filter(Boolean);body=`<h2>Build the sentence</h2><p class="prompt">${esc(q.prompt)}</p><div class="slots" aria-label="Your sentence">${selected.length?selected.map(t=>`<button class="chip placed" data-act="remove-tile" data-key="${t.key}"><b>${esc(t.ja)}</b><small class="romaji">${esc(t.romaji)}</small></button>`).join(''):''}</div><div class="bank">${q.tiles.filter(t=>!used.has(t.key)).map(t=>`<button class="chip" data-act="add-tile" data-key="${t.key}" ${fb?'disabled':''}><b>${esc(t.ja)}</b><small class="romaji">${esc(t.romaji)}</small></button>`).join('')}</div><button class="btn" data-act="check-tiles" ${tiles.length?'':'disabled'} ${fb?'disabled':''}>Check sentence</button>`;}
    if(q.type==='romaji')body=`<div class="bigword">${japanese(q)}</div><h2>${esc(q.prompt)}</h2><form id="romaji-form"><label for="romaji-answer">Romaji</label><input class="typein" id="romaji-answer" type="text" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="e.g. arigatō or arigatou" ${fb?'disabled':''}><button class="btn" type="submit" ${fb?'disabled':''}>Check romaji</button></form>`;
    if(q.type==='match'){const done=new Set(match.done),left=q.pairs.filter(p=>!done.has(p.key)),right=E.shuffle(q.pairs.slice(),E.rng((session.seed||1)+session.index+12)).filter(p=>!done.has(p.key));body=`<h2>Match the expressions</h2><div class="match"><div class="mcol">${left.map(p=>`<button data-act="match-left" data-key="${p.key}" class="mbtn left ${match.left===p.key?'sel':''}">${esc(p.ja)}<small class="romaji">${esc(p.romaji)}</small></button>`).join('')}</div><div class="mcol">${right.map(p=>`<button data-act="match-right" data-key="${p.key}" class="mbtn ${match.right===p.key?'sel':''}">${esc(p.meaning)}</button>`).join('')}</div></div><p>${match.done.length}/${q.pairs.length} matched</p>${match.errors?`<p class="match-feedback" role="status">${match.errors===1?"That pair did not match. Try another pair.":`${match.errors} pairs did not match. Keep trying.`}</p>`:""}`;}
    if(q.type==='sort'){const current=q.entries.find(e=>sort[e.key]===undefined);body=`<h2>${esc(q.prompt)}</h2>${current?`<div class="bucketcard">${esc(current.text)}</div><div class="buckets">${q.buckets.map(b=>`<button class="bucketbtn" data-act="sort" data-key="${current.key}" data-value="${attr(b)}">${esc(b)}</button>`).join('')}</div><p>${Object.keys(sort).length}/${q.entries.length} sorted</p>`:`<p>All entries sorted.</p><button class="btn" data-act="check-sort" ${fb?'disabled':''}>Check sorting →</button>`}`;}
    return body;
  }
  function feedbackBody(q,fb){const it=ix.items.get(q.itemId);return fb?`<div class="fb-body" role="status">${q.type==='listen'?`<div class="bigword sentence">${japanese(q)}</div><div class="sub romaji">${esc(q.romaji)}</div><p>${esc(q.meaning)}</p>`:''}${q.type==='romaji'?`<div class="sub">${esc(q.answer)}</div>`:''}${q.type==='tiles'?`<div class="bigword sentence">${japanese(q)}</div><div class="sub romaji">${esc(q.romaji)}</div>`:''}${q.type==='sort'?`<ul class="sort-review">${q.entries.map(e=>`<li><b>${esc(e.text)}</b> → ${esc(e.bucket)}. ${esc(e.why)}</li>`).join('')}</ul>`:''}${q.type==='scenario'?`<p><b>Best here:</b> ${esc(q.options[q.answer]?.text)}</p><p>${esc(q.options[q.answer]?.why)}</p>${!fb.correct?`<p><b>Your choice:</b> ${esc(q.options[fb.value]?.why)}</p>`:''}`:`${q.type==='choice'&&q.meaning?`<p class="feedback-correct-answer">${esc(q.meaning)}</p>`:''}<p>${esc(q.explain||q.say)}</p>`}${sourceLink(it)}</div>`:'';}
  function dialoguePanel(l){return l?`<section class="card col" style="width:100%;text-align:left"><div class="eyebrow">Now make it a conversation</div><h2>${esc(l.title)}</h2>${l.dialogue?.length?`<div class="exlist">${l.dialogue.map(d=>`<div class="ex"><b>${esc(d.speaker)}</b><span>${japanese(d)} <small class="romaji">${esc(d.romaji)}</small></span><em>${esc(d.meaning)}</em>${audioButton(d.ja,'Hear line')}</div>`).join('')}</div>`:''}<p><b>Your mission:</b> ${esc(l.mission)}</p><p class="muted">Say your lines before listening. Playback is practice, not a pronunciation grade.</p></section>`:'';}
  function lessonIntro(){const l=ix.lessonById.get(session.lessonId),u=ix.units.find(x=>x.lessons.includes(l));return `<div class="intro"><span class="eyebrow">${esc(u?.place||'Tokyo')} · ${esc(l.title)}</span><h2>In this scene</h2><p>${esc(l.scene)}</p>${l.mission?`<p class="card col"><b>Your field mission</b><br>${esc(l.mission)}</p>`:''}<p class="muted">Say a useful phrase aloud when you hear it. Your browser cannot grade pronunciation; you decide when you are ready.</p></div>`;}
  function sessionPage(){if(!session)return '';const step=session.steps[session.index];if(session.mode==='speed'&&!feedback&&!session.intro&&!session.deadline)session.deadline=Date.now()+15000;const l=session.lessonId&&ix.lessonById.get(session.lessonId),title=session.mode==='lesson'?l?.title:({review:'Spaced review',daily:'Daily drill',speed:'Lantern sprint',mistakes:'Mistakes notebook',assessment:'Scenario assessment',match:'Word matching',sort:'Word sorting',listening:'Listening drill',kana:'Kana garden'})[session.mode]||'Practice';const pct=Math.round(session.index/Math.max(1,session.steps.length)*100),fb=feedback;return `<div class="lesson"><div class="lesson-inner"><div class="lesson-top"><button class="xbtn" data-act="exit-session" aria-label="Leave practice">${I.x}</button><div class="progress" role="progressbar" aria-label="Practice progress" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct}"><i style="width:${pct}%"></i></div><div class="combo">${Math.min(session.index+1,session.steps.length)}/${session.steps.length}</div></div>${session.mode==='speed'?`<div class="timer"><i></i></div>`:''}<div class="stage"><div class="qlabel ${step?.guess?'guess':''}">${esc(title)}${session.mode==='speed'?`<span class="marks" id="speed-timer" aria-live="off">15s</span>`:''}</div>${session.intro?lessonIntro():step?`<div class="qlabel ${step.guess?'guess':''}">${esc(step.label||'Look and learn')}</div>${step.type==='teach'?teachCard(ix.items.get(step.itemId)):step.type==='kana-teach'?`<div class="intro"><div class="bigword" lang="ja">${esc(step.ja)}</div><h2>${esc(step.romaji)}</h2>${audioButton(step.ja)}<p>Look, listen, then recall the reading.</p></div>`:questionCard(step)}`:'<p>All done.</p>'}</div></div><div class="footer ${fb?(fb.correct||fb.ungraded?'right':'wrong'):''}"><div class="footer-inner">${fb?`<div class="fb-title">${fb.ungraded?'Meaning revealed':fb.correct?'That works.':'Keep going.'}</div>${feedbackBody(step,fb)}<button class="btn block ${fb.correct||fb.ungraded?'olive':'clay'}" data-act="next">Continue</button>`:session.intro?'<button class="btn block gold" data-act="lesson-begin">Begin sitting</button>':['teach','kana-teach'].includes(step?.type)?'<button class="btn block gold" data-act="next">Try it</button>':'<p class="muted" style="text-align:center;font-weight:700">No hearts. Every attempt is useful.</p>'}</div></div></div>`;}
  function resultPage(){const r=session?.result||{},mode=session?.mode,sub=mode==='listening'&&!voices.length?'Visual and speak-aloud practice complete. This was ungraded because no Japanese voice is available.':mode==='assessment'?(session.repeatedAssessment?'Repeat practice completed. These scenes were seen before.':'First attempt completed on these held-out scenes. They do not enter spaced review.'):mode==='sort'||mode==='match'?'Practice complete. Try these words again whenever you like; sorting and matching do not schedule individual cards.':mode==='speed'?(r.wrong?'The round stopped at your first miss. Try again when you are ready.':'You made it through this speed round.'):(r.wrong?(mode==='kana'?'Missed symbols will return in the kana garden tomorrow.':'The missed cards are in your notebook and will return tomorrow.'):'Your next review is already on its way.');return `<div class="lesson"><div class="lesson-inner"><div class="results">${mascot('cheer')}<h1>Sitting complete</h1><div class="resgrid"><div class="res gold"><div class="h">First try</div><div class="v">${r.correct||0}</div></div><div class="res olive"><div class="h">Questions</div><div class="v">${r.total||0}</div></div><div class="res flame"><div class="h">Streak</div><div class="v">${E.liveStreak(state,today())}</div></div></div><p class="story">${mode==='listening'&&!voices.length?'No listening score':`${r.correct||0} of ${r.total||0} questions answered on the first try.`}</p><p class="muted">${esc(sub)}</p>${session?.lessonId&&state.done[session.lessonId]?dialoguePanel(ix.lessonById.get(session.lessonId)):''}${session?.newBadges?.length?`<div class="card col">${session.newBadges.map(b=>`<b>${esc(b.name)}</b>`).join('')}<span>New milestone earned</span></div>`:''}</div></div><div class="footer"><div class="footer-inner">${session?.lessonId&&!state.done[session.lessonId]?'<button class="btn block gold" data-act="continue-lesson">Continue lesson</button><button class="linkbtn" data-act="finish-session">Back to Learn</button>':'<button class="btn block gold" data-act="finish-session">Back to Learn</button>'}</div></div></div>`;}
  function footer(){return `<footer class="sitenote"><p><a href="/about/">About Komorebi</a> · <a href="/glossary/">Glossary</a></p><p>More learning: ${FAMILY.filter(a=>a.id!=="komorebi").map(a=>`<a href="${a.url}" target="_blank" rel="noopener noreferrer">${a.name}</a> (<a href="${a.repo}" target="_blank" rel="noopener noreferrer" aria-label="${a.name} on GitHub">GitHub</a>)`).join(" · ")}</p><p><a href="${REPO}" target="_blank" rel="noopener noreferrer">Built with the Skepsis learning family</a></p><p>Progress stays in this browser. No account or learning analytics. Export a backup from Me.</p></footer>`;}
  function top(){window.scrollTo(0,0);}
  function render(){if(timerId){clearInterval(timerId);timerId=null;}document.documentElement.dataset.theme=state.theme;document.documentElement.dataset.romaji=state.showRomaji===false?'hide':'show';document.documentElement.dataset.kana=state.showKana===false?'hide':'show';document.body.classList.toggle('run-open',['session','result'].includes(view));if(!state.onboarded){root.innerHTML=header()+onboarding();return;}if(view==='session'||view==='result'){root.innerHTML=view==='session'?sessionPage():resultPage();}else{const body=view==='home'?home():view==='map'?map():view==='unit'?unitPage():view==='review'?reviewPage():view==='glossary'?glossary():view==='settings'?settings():view==='kana'?kanaPage():view==='culture'?culturePage():home();root.innerHTML=header()+`<main class="view">${body}${footer()}</main>`+tabbar();}if(view==='session'&&session?.mode==='speed'&&!feedback&&!session.intro){timerId=setInterval(()=>{const left=Math.max(0,Math.ceil((session.deadline-Date.now())/1000));const el=document.getElementById('speed-timer');if(el)el.textContent=left+'s';if(left<=0){clearInterval(timerId);timerId=null;recordAnswer(session.steps[session.index],false,'time');}},200);}}
  function start(mode,id){let steps=[];const seed=Date.now()%1000000;
    if(mode==='lesson'){const sitting=state.done[id]?(state.revisits[id]||0):(state.sittings[id]||0);const chunks=E.lessonSittings(ix,id);steps=E.buildLesson(ix,state,id,seed,Math.min(sitting,Math.max(0,chunks.length-1)));}
    if(mode==='kana')steps=Kana.build(state,kanaScript,kanaRow,today(),seed);
    if(mode==='review')steps=E.buildReview(ix,state,today(),seed);
    if(mode==='daily')steps=E.buildDaily(ix,state,today());
    if(mode==='speed')steps=E.buildSpeed(ix,state,today(),seed);
    if(mode==='listening')steps=E.buildListening(ix,state,seed);
    if(mode==='assessment')steps=E.buildAssessment(ix,state,id,seed);
    if(mode==='match'){const q=E.buildMatch(ix,state,today(),seed);if(q)steps=[q];}
    if(mode==='sort'){const q=E.buildSort(ix,state,seed);if(q)steps=[q];}
    if(mode==='mistakes')steps=Object.keys(state.mistakes).filter(x=>ix.items.has(x)&&!ix.assessmentItems.has(x)).sort((a,b)=>state.mistakes[b]-state.mistakes[a]).slice(0,12).map(x=>E.question(ix.items.get(x),E.rng(seed),'review')).filter(Boolean);
    if(!steps.length){notice=mode==='review'?'No cards are due today. Try a lesson or the daily drill.':'This activity opens after you learn a few cards in a lesson.';view=mode==='lesson'?'unit':'review';render();return;}
    session={startedAt:Date.now(),stepAt:Date.now(),mode,repeatedAssessment:mode==='assessment'&&(!!state.assessmentSeen[id]||state.assessments.some(a=>a.unitId===id)),revisit:mode==='lesson'&&!!state.done[id],lessonId:mode==='lesson'?id:null,unitId:mode==='assessment'?id:null,steps,index:0,seed,intro:mode==='lesson',correct:0,total:0,wrong:0,wrongSteps:[],retried:false};feedback=null;tiles=[];match={left:null,right:null,done:[]};sort={};if(mode==='assessment'){state.assessmentSeen[id]=today();save();}view='session';track('lesson_started',runProps());render();top();}
  function answer(value){if(!session||feedback)return;const q=session.steps[session.index];const correct=q.type==='scenario'?Number(value)===q.answer:E.norm(value)===E.norm(q.answer);recordAnswer(q,correct,value);}
  function recordAnswer(q,correct,value){if(!session||feedback)return;if(timerId){clearInterval(timerId);timerId=null;}if(!q.guess){session.total++;if(correct)session.correct++;else{session.wrong++;if(!session.retried&&session.mode!=='speed')session.wrongSteps.push(q);if(session.mode==='speed')session.stopAfterFeedback=true;}if(session.mode==='assessment'){state.answered++;if(correct)state.correct++;}else if(session.mode==='kana'){Kana.grade(state,q.itemId,correct,today());state.answered++;if(correct)state.correct++;}else E.grade(state,q.itemId,correct,today());save();}track('question_answered',{...runProps(),q_type:q.type,item_id:q.itemId||null,correct:!!correct,graded:!q.guess,ms:Date.now()-session.stepAt});feedback={correct,value};render();}
  function next(){if(!session)return;if(feedback===null&&!['teach','kana-teach'].includes(session.steps[session.index]?.type))return;if(session.stopAfterFeedback){finish();return;}feedback=null;tiles=[];match={left:null,right:null,done:[]};sort={};session.deadline=null;session.index++;session.stepAt=Date.now();
    if(session.index>=session.steps.length){if(session.wrongSteps.length&&!session.retried){session.steps=session.steps.concat(session.wrongSteps.map(q=>({...q,retry:true,guess:true,label:'One more try'})));session.wrongSteps=[];session.retried=true;}
      else{finish();return;}}
    render();top();}
  function finish(){const beforeBadges=new Set(Object.keys(state.badges));const s=session,sr={correct:s.correct,total:s.total,wrong:s.wrong};if(s.mode==='lesson'){const count=E.lessonSittings(ix,s.lessonId).length;if(s.revisit){state.revisits[s.lessonId]=((state.revisits[s.lessonId]||0)+1)%count;E.recordPractice(ix,state,today(),5);}else{state.sittings[s.lessonId]=Math.min(count,(state.sittings[s.lessonId]||0)+1);if(state.sittings[s.lessonId]>=count)E.recordLesson(ix,state,s.lessonId,today(),!s.wrong);else E.recordPractice(ix,state,today(),5);}}
    else if(s.mode==='assessment')E.recordAssessment(ix,state,s.unitId,today(),s.correct,s.total);
    else{if(s.mode==='review')state.reviewSessions++;E.recordPractice(ix,state,today(),s.mode==='speed'?Math.max(3,s.correct):5);if(s.mode==='daily')state.daily[today()]={score:s.correct,total:s.total};if(s.mode==='speed')state.speedBest=Math.max(state.speedBest,s.correct);}
    track('lesson_completed',{...runProps(),accuracy:s.total?s.correct/s.total:null,seconds:Math.round((Date.now()-s.startedAt)/1000),misses:s.wrong});session.result=sr;session.newBadges=E.BADGES.filter(b=>state.badges[b.id]&&!beforeBadges.has(b.id));save();view='result';render();top();}
  root.addEventListener('click',ev=>{const b=ev.target.closest('[data-act]');if(!b||b.disabled)return;const a=b.dataset.act,id=b.dataset.id;
    if(a==='onboard-goal'){state.name=document.getElementById('ob-name')?.value.trim()||'';state.goal=Number(b.dataset.value);render();return;}
    if(a==='set-goal'){state.goal=Number(b.dataset.value);save();root.querySelectorAll('[data-act="set-goal"]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));return;}
    if(a==='start-course'){state.name=document.getElementById('ob-name')?.value.trim()||'';state.onboarded=true;save();track('onboarding_completed',{goal:state.goal});view='home';render();top();return;}
    if(a==='kana-script'){kanaScript=b.dataset.value;render();return;}
    if(a==='home'||a==='kana'||a==='culture'||a==='map'||a==='review'||a==='glossary'||a==='settings'){view=a;session=null;notice='';render();top();return;}
    if(a==='open-unit'){selectedUnit=id;view='unit';render();top();return;}
    if(a==='start-lesson'||a==='start-review'||a==='start-daily'||a==='start-speed'||a==='start-assessment'||a==='start-mistakes'||a==='start-match'||a==='start-sort'||a==='start-listening'||a==='start-kana'){start(a.replace('start-',''),id);return;}
    if(a==='lesson-begin'){session.intro=false;session.stepAt=Date.now();render();top();return;}
    if(a==='speak'||a==='slow'){speak(b.dataset.text,a==='slow');return;}
    if(a==='answer'){answer(b.dataset.value);return;}
    if(a==='listen-reveal'){feedback={ungraded:true,correct:true};render();return;}
    if(a==='add-tile'){const k=Number(b.dataset.key);if(!tiles.includes(k)){tiles.push(k);render();}return;}
    if(a==='remove-tile'){if(feedback)return;tiles=tiles.filter(k=>k!==Number(b.dataset.key));render();return;}
    if(a==='check-tiles'){const q=session.steps[session.index],picked=tiles.map(k=>q.tiles.find(t=>t.key===k)?.ja);recordAnswer(q,picked.length===q.answer.length&&picked.every((x,i)=>x===q.answer[i]),picked.join(''));return;}
    if(a==='match-left'||a==='match-right'){match[a==='match-left'?'left':'right']=Number(b.dataset.key);if(match.left!==null&&match.right!==null){if(match.left===match.right)match.done.push(match.left);else match.errors=(match.errors||0)+1;match.left=null;match.right=null;}const q=session.steps[session.index];if(match.done.length===q.pairs.length){recordAnswer(q,!match.errors,'all matched');}else render();return;}
    if(a==='sort'){sort[Number(b.dataset.key)]=b.dataset.value;render();return;}
    if(a==='check-sort'){const q=session.steps[session.index];recordAnswer(q,q.entries.every(e=>sort[e.key]===e.bucket),'sorted');return;}
    if(a==='next'){next();return;}
    if(a==='exit-session'){track('lesson_quit',{...runProps(),seconds:session?Math.round((Date.now()-session.startedAt)/1000):0});if(timerId){clearInterval(timerId);timerId=null;}session=null;view='home';render();top();return;}
    if(a==='continue-lesson'){const lessonId=session?.lessonId;if(lessonId)start('lesson',lessonId);return;}
    if(a==='finish-session'){session=null;view='home';render();top();return;}
    if(a==='save-settings'){state.name=document.getElementById('setting-name').value.trim();state.theme=document.getElementById('setting-theme').value;state.voice=document.getElementById('setting-voice').value;state.showRomaji=document.getElementById('setting-romaji').checked;state.showKana=document.getElementById('setting-kana').checked;save();notice='Settings saved.';view='home';render();top();return;}
    if(a==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`komorebi-progress-${today()}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
  });
  function nextUngraded(){if(!session)return;feedback=null;tiles=[];match={left:null,right:null,done:[]};sort={};session.deadline=null;session.index++;session.stepAt=Date.now();if(session.index>=session.steps.length)finish();else{render();top();}}
  root.addEventListener('submit',ev=>{if(ev.target.id!=='romaji-form')return;ev.preventDefault();const q=session?.steps[session.index],value=document.getElementById('romaji-answer')?.value||'';if(q&&q.type==='romaji'&&value.trim())recordAnswer(q,E.acceptsRomaji(q.answer,value),value);});
  root.addEventListener('input',ev=>{if(ev.target.id==='word-search'){const term=E.norm(ev.target.value),words=[...ix.items.values()].filter(it=>['word','character'].includes(it.kind)&&E.norm([it.ja,it.kana,it.romaji,it.meaning].join(' ')).includes(term));document.getElementById('word-list').innerHTML=wordRows(words);}});
  root.addEventListener('change',async ev=>{if(ev.target.id==='kana-row'){kanaRow=ev.target.value;render();return;}if(ev.target.id!=='import-file')return;const file=ev.target.files?.[0];if(!file)return;try{if(file.size>2e6)throw Error('File is too large.');const parsed=JSON.parse(await file.text());if(!parsed||typeof parsed!=='object'||parsed.app!=='komorebi'||!parsed.items||!parsed.done)throw Error('This is not a Komorebi progress file.');state=E.repairState(parsed);if(!state.onboarded&&(state.xp>0||state.answered>0||Object.keys(state.done||{}).length||Object.keys(state.sittings||{}).length||Object.keys(state.items||{}).length))state.onboarded=true;save();notice='Progress imported.';view='home';render();top();}catch(err){notice=err.message||'Could not import this file.';view='settings';render();}});
  document.addEventListener('keydown',ev=>{if(/INPUT|SELECT|TEXTAREA/.test(ev.target?.tagName)||ev.ctrlKey||ev.metaKey||ev.altKey)return;if(view!=='session')return;const q=session?.steps[session.index];if(ev.key==='Enter'){const button=root.querySelector('[data-act="next"], [data-act="lesson-begin"]');if(button){ev.preventDefault();button.click();}}else if(/^[1-4]$/.test(ev.key)&&!feedback&&q?.options){const buttons=root.querySelectorAll('[data-act="answer"]');const button=buttons[Number(ev.key)-1];if(button){ev.preventDefault();button.click();}}});
  render();
})();
